import json
import gurobipy as gp
from gurobipy import GRB

# Coefficients
a = 70
b = 100
# Data from table
buying_prices = [410, 430, 460, 450]
selling_prices = [425, 440, 465, 455]
max_sales_volumes = [100, 140, 200, 160]

# Model
m = gp.Model()

# Decision variables
x_winter = m.addVar(vtype=gp.GRB.INTEGER, name="x_winter")
x_spring = m.addVar(vtype=gp.GRB.INTEGER, name="x_spring")
x_summer = m.addVar(vtype=gp.GRB.INTEGER, name="x_summer")
x_autumn = m.addVar(vtype=gp.GRB.INTEGER, name="x_autumn")
y = m.addVar(vtype=gp.GRB.CONTINUOUS, name="y")

# Constraints
m.addConstr(x_winter + x_spring + x_summer + x_autumn <= 200, "storage_limit")
m.addConstr((buying_prices[0] - selling_prices[0]) * x_winter + a * 100 + b * y >= 70 * 100, "winter_storage_cost")
m.addConstr((buying_prices[1] - selling_prices[1]) * x_spring + a * 100 + b * y >= 70 * 100, "spring_storage_cost")
m.addConstr((buying_prices[2] - selling_prices[2]) * x_summer + a * 100 + b * y >= 70 * 100, "summer_storage_cost")
m.addConstr((buying_prices[3] - selling_prices[3]) * x_autumn + a * 100 + b * y >= 70 * 100, "autumn_storage_cost")
m.addConstr((selling_prices[0] - buying_prices[0]) * x_winter + a * 100 + b * y >= max_sales_volumes[0] * 100, "winter_profit")
m.addConstr((selling_prices[1] - buying_prices[1]) * x_spring + a * 100 + b * y >= max_sales_volumes[1] * 100, "spring_profit")
m.addConstr((selling_prices[2] - buying_prices[2]) * x_summer + a * 100 + b * y >= max_sales_volumes[2] * 100, "summer_profit")
m.addConstr((selling_prices[3] - buying_prices[3]) * x_autumn + a * 100 + b * y >= max_sales_volumes[3] * 100, "autumn_profit")

# Objective
m.setObjective(100 * y, GRB.MAXIMIZE)

# Optimize
m.optimize()

# Print results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {v.varName: v.x for v in m.getVars()}}))

