import json
import gurobipy as gp
from gurobipy import GRB

# Constants
a, b, c, d, m, n = 4, 5, 100, 10, 1000, 2000

# Create a model
m = gp.Model()

# Create variables
x1 = m.addVar(vtype=gp.GRB.INTEGER, name="x1")
x2 = m.addVar(vtype=gp.GRB.INTEGER, name="x2")

# Add constraints
m.addConstr(x1 + x2 <= c, "c1")
m.addConstr(a*x1 + b*x2 >= d, "c2")

# Set objective
m.setObjective(m*x1 + n*x2, GRB.MINIMIZE)

# Optimize model
m.optimize()

# Print results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {v.varName: v.x for v in m.getVars()}}))
