# Create a new model
m = Model("salesperson")

# Create variables
x = {}
for city1 in range(1, 6):
    for city2 in range(1, 6):
        if city1 != city2:
            x[city1, city2] = m.addVar(vtype=INT, name=f"x{city1}{city2}")

y = m.addVar(vtype=REAL, name="y")

# Add constraints
for city1 in range(1, 6):
    m.addConstr(sum(x[city1, city2] for city2 in range(1, 6) if city2 != city1) == 1, name=f"c1{city1}")
    m.addConstr(sum(x[city2, city1] for city2 in range(1, 6) if city2 != city1) == 1, name=f"c2{city1}")

for city1 in range(1, 6):
    for city2 in range(1, 6):
