            m.addConstr(x[city1, city2] + x[city2, city1] == 1, name=f"c3{city1}{city2}")

# Add objective
m.setObjective(y, GRB.MINIMIZE)

# Optimize model
m.optimize()

# Extract solution
solution = {"objective_value": float(m.objVal), "assignment": {v.varName: v.x for v in m.getVars()}}
