import json
from gurobipy import *

# Data
profit_first_type = 9
profit_second_type = 8
assembly_first_type = 1/4
assembly_second_type = 1/3
test_first_type = 1/8
test_second_type = 1/3
raw_material_first_type = 1.2
raw_material_second_type = 0.9
max_assembly = 90
max_test = 80
max_overtime_assembly = 50
overtime_cost = 7

# Model
m = Model("production_optimization")
x = m.addVar(vtype=GRB.INTEGER, name="x")
y = m.addVar(vtype=GRB.INTEGER, name="y")

# Constraints
m.addConstr(assembly_first_type * x + assembly_second_type * y <= max_assembly, "c1")
m.addConstr(test_first_type * x + test_second_type * y <= max_test, "c2")
m.addConstr(overtime_cost * x <= max_overtime_assembly, "c3")

# Objective
m.setObjective(profit_first_type * x + profit_second_type * y, GRB.MAXIMIZE)

# Optimize
m.optimize()

# Results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {x.VarName: x.X, y.VarName: y.X}}))

