import json
from gurobipy import *

# Problem data
x_lb, x_ub = 0, None
y_lb, y_ub = 0, 100
x_coef = 50
y_coef = 35
x_demand = 100
y_demand = 100
raw_material = 30
raw_material_demand = 3000
selling_price_x = 100
selling_price_y = 90
cost_x = 50
cost_y = 35
cash_initial = 10000
accounts_receivable_initial = 3000
inventory_initial = 7000
loan_initial = 10000
current_ratio_initial = 2
rent = 1000
accounts_receivable_collected = 2000
loan_payment = 1000
cash_target = 4000
current_ratio_target = 2

# Create a new model
m = Model("production_optimization")

# Create variables
x = m.addVar(lb=x_lb, ub=x_ub, name="x")
y = m.addVar(lb=y_lb, ub=y_ub, name="y")

# Objective function
m.setObjective(x_coef * x + y_coef * y, sense=maximize)

# Constraints
m.addConstr(x * x_coef + y * y_coef >= cash_initial + accounts_receivable_initial - loan_initial - rent - accounts_receivable_collected, name="c1")
m.addConstr(x * selling_price_x + y * selling_price_y >= cash_initial + accounts_receivable_initial - loan_initial - rent - accounts_receivable_collected, name="c2")
m.addConstr(x * raw_material + y * raw_material >= raw_material_demand, name="c3")
m.addConstr(x * cost_x + y * cost_y <= cash_initial + accounts_receivable_initial - loan_initial - rent - accounts_receivable_collected, name="c4")
m.addConstr(x * selling_price_x + y * selling_price_y >= cash_initial + accounts_receivable_initial - loan_initial - rent - accounts_receivable_collected, name="c5")
m.addConstr(x * raw_material + y * raw_material >= raw_material_demand, name="c6")
m.addConstr(x + y >= current_ratio_initial, name="c7")
m.addConstr(x + y >= current_ratio_target, name="c8")

# Optimize model
m.optimize()

# Extract results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {v.varName: v.x for v in m.getVars()}}))

