m.setObjective(meals_per_bike * bikes + meals_per_scooter * scooters, sense=GRB.MAXIMIZE)

# Constraints
m.addConstr(bikes * charge_per_bike + scooters * charge_per_scooter <= total_charge, "charge_constraint")
m.addConstr(bikes <= max_bikes * scooters, "bike_limit")
m.addConstr(scooters >= min_scooters, "scooter_min")

# Optimize the model
m.optimize()

# Extract results
objective_value = float(m.objVal)
assignment = {var.VarName: var.X for var in m.getVars()}

# Print the results
print(json.dumps({"objective_value": objective_value, "assignment": assignment}))
