import json
from gurobipy import *

# Data
morphine_total = 3000
painkillers_morphine = 10
sleeping_pills_morphine = 6
painkillers_units = 3
sleeping_pills_units = 5
min_painkillers = 50
sleeping_pills_percentage = 0.7

# Model
m = Model("morphine_pills")
x = m.addVar(vtype=INT, name="painkillers", lb=0, ub=None)
y = m.addVar(vtype=INT, name="sleeping_pills", lb=0, ub=None)

# Constraints
m.addConstr(x * painkillers_morphine + y * sleeping_pills_morphine <= morphine_total, "morphine_limit")
m.addConstr(x >= min_painkillers, "painkillers_min")
m.addConstr(y <= x, "sleeping_pills_max")
m.addConstr(y >= sleeping_pills_percentage * (x + y), "sleeping_pills_percentage")

# Objective
m.setObjective(x * sleeping_pills_units, GRB.MINIMIZE)

# Optimize
m.optimize()

# Results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {x.VarName: x.X, y.VarName: y.X}}))
