import json
import gurobipy as gp
from gurobipy import GRB

# Problem data
packages_needed = 500
max_trucks = 5
min_car_percentage = 0.3

# Create a new model
m = gp.Model("transportation")

# Data
trucks = m.addVar(vtype=gp.GRB.INTEGER, name="trucks", lb=0)
cars = m.addVar(vtype=gp.GRB.INTEGER, name="cars", lb=0)

# Objective function
m.setObjective(20 * trucks + 15 * cars, GRB.MINIMIZE)

# Constraints
m.addConstr(30 * cars + 50 * trucks >= packages_needed, "packages_constraint")
m.addConstr(trucks <= max_trucks, "trucks_limit")
m.addConstr(cars >= min_car_percentage * (1 + trucks + cars), "car_percentage")

# Optimize the model
m.optimize()

# Extract results
result = {
    "objective_value": float(m.objVal),
    "assignment": {
        "trucks": trucks.X,
        "cars": cars.X
    }
}

# Print the results
print(json.dumps(result))

