from gurobipy import *

# Data
assembly_time = {'X': 1, 'Y': 2, 'Z': 3}
inspection_time = {'X': 2, 'Y': 3, 'Z': 4}
storage_space = {'X': 3, 'Y': 4, 'Z': 5}
profit = {'X': 100, 'Y': 125, 'Z': 200}
min_model_x = 12
max_model_z_fraction = 0.25

