m = Model('comp_max')
x, y, z = m.addVars(['X', 'Y', 'Z'], vtype=INT, name='x', obj=profit)
m.addConstr(assembly_time['X'] * x + assembly_time['Y'] * y + assembly_time['Z'] * z <= 400, 'assembly_time')
m.addConstr(inspection_time['X'] * x + inspection_time['Y'] * y + inspection_time['Z'] * z <= 300, 'inspection_time')
m.addConstr(storage_space['X'] * x + storage_space['Y'] * y + storage_space['Z'] * z <= 500, 'storage_space')
m.addConstr(x >= min_model_x, 'model_x_min')
m.addConstr(z <= max_model_z_fraction * (x + y + z), 'model_z_max')

# Optimize
m.optimize()

# Output result
print(json.dumps({"objective_value": float(m.objVal), "assignment": {v.varName: v.X for v in m.getVars()}}))

