import json
import gurobipy as gp

# Problem data
vitamin_requirement = 90
fibre_requirement = 110
salads_per_staff = 1
fruit_bowls_per_staff = 1
vitamin_per_salad = 7
fibre_per_salad = 12
vitamin_per_fruit_bowl = 15
fibre_per_fruit_bowl = 3
potassium_per_salad = 2
potassium_per_fruit_bowl = 8
fruit_bowl_limit = 0.3

# Model creation
m = gp.Model("nutritionist")

# Decision variables
salads = m.addVar(vtype=gp.GRB.INTEGER, name="salads")
fruit_bowls = m.addVar(vtype=gp.GRB.INTEGER, name="fruit_bowls")

# Constraints
m.addConstr(salads * vitamin_per_salad + fruit_bowls * vitamin_per_fruit_bowl >= vitamin_requirement, "vitamin_requirement")
m.addConstr(salads * fibre_per_salad + fruit_bowls * fibre_per_fruit_bowl >= fibre_requirement, "fibre_requirement")
m.addConstr(fruit_bowls <= fruit_bowl_limit * (salads + fruit_bowls), "fruit_bowl_limit")

# Objective
m.setObjective(salads * potassium_per_salad + fruit_bowls * potassium_per_fruit_bowl, gp.GRB.MAXIMIZE)

# Optimization
m.optimize()

# Results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {v.varName: v.x for v in m.getVars()}}))
