m.addConstr(high_volume_pipes * 10000 + low_volume_pipes * 5000 >= demand_gallons, "demand_constraint")
m.addConstr(high_volume_pipes * monitoring_req_high + low_volume_pipes * monitoring_req_low <= technicians, "monitoring_constraint")
m.addConstr(high_volume_pipes <= max_high_volume * (technicians - min_low_volume), "max_high_volume")
m.addConstr(low_volume_pipes >= min_low_volume, "min_low_volume")

# Objective
m.setObjective(high_volume_pipes, GRB.MINIMIZE)

# Optimize
m.optimize()

# Results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {var.VarName: var.X for var in m.getVars()}}))

