total_ice_cream = 600
total_water = 550

# Model
m = Model("dessert_shop")
matcha_ice_cream = m.addVar(vtype=INT, name="matcha_ice_cream", lb=0)
orange_sorbet = m.addVar(vtype=INT, name="orange_sorbet", lb=0)

# Constraints
m.addConstr(matcha_ice_cream * flavouring_per_matcha + orange_sorbet * flavouring_per_orange_sorbet <= total_ice_cream, "flavouring_constraint")
m.addConstr(orange_sorbet * water_per_orange_sorbet <= total_water, "water_constraint")
m.addConstr(matcha_ice_cream >= min_matcha_ratio * (matcha_ice_cream + orange_sorbet), "matcha_ratio_constraint")

# Objective
m.setObjective(matcha_ice_cream * flavouring_per_matcha, GRB.MINIMIZE)

# Optimize
m.optimize()

# Result
print(json.dumps({"objective_value": float(m.objVal), "assignment": {v.varName: v.x for v in m.getVars()}}))
