distances = {
    (0, 1): 318, (0, 2): 278, (0, 3): 304, (0, 4): 287, (0, 5): 277,
    (1, 0): 285, (1, 2): 277, (1, 3): 322, (1, 4): 277, (1, 5): 306,
    (2, 0): 275, (2, 1): 302, (2, 3): 299, (2, 4): 277, (2, 5): 291,
    (3, 0): 282, (3, 1): 292, (3, 2): 276, (3, 4): 283, (3, 5): 304,
    (4, 0): 277, (4, 1): 301, (4, 2): 291, (4, 3): 306, (4, 5): 325,
    (5, 0): 325, (5, 1): 319, (5, 2): 306, (5, 3): 279, (5, 4): 275
}

# Create a new model
m = gp.Model("delivery_route")

# Create variables
x = {}
for i in range(6):
    for j in range(6):
        if i != j:
            x[i, j] = m.addVar(vtype=gp.GRB.BINARY, name=f"x{i}_{j}")

# Set objective
m.setObjective(sum(x[i, j] for i in range(6) for j in range(6) if i != j), GRB.MINIMIZE)

# Add constraints
for i in range(6):
    m.addConstr(sum(x[i, j] for j in range(6) if j != i) == 1, name=f"c1_{i}")
    m.addConstr(sum(x[j, i] for j in range(6) if j != i) == 1, name=f"c2_{i}")

for i in range(6):
    for j in range(6):
        if i != j:
            m.addConstr(x[i, j] <= x[i, 0], name=f"c3_{i}_{j}")

# Optimize model
m.optimize()

# Extract results
solution = {}
for v in m.getVars():
    solution[v.varName] = v.x

print(json.dumps({"objective_value": m.objVal, "assignment": solution}))

