import json
import gurobipy as gp
from gurobipy import GRB

# Data
max_loads = [2000, 3000, 1500]
volumes = [4000, 5000, 1500]
freight_rates = [1000, 700, 600]
volume_per_piece = [10, 5, 7]
weight_per_piece = [8, 6, 4]

# Model
m = gp.Model("cargo_ship")

# Variables
A = m.addVar(vtype=gp.GRB.INTEGER, name="A")
B = m.addVar(vtype=gp.GRB.INTEGER, name="B")
C = m.addVar(vtype=gp.GRB.INTEGER, name="C")

# Objective
m.setObjective(A*freight_rates[0] + B*freight_rates[1] + C*freight_rates[2], sense=gp.GRB.MAXIMIZE)

# Constraints
m.addConstr(A*volume_per_piece[0] + B*volume_per_piece[1] + C*volume_per_piece[2] <= volumes[0], "Volume_Front")
m.addConstr(A*volume_per_piece[0] + B*volume_per_piece[1] + C*volume_per_piece[2] <= volumes[1], "Volume_Middle")
m.addConstr(A*volume_per_piece[0] + B*volume_per_piece[1] + C*volume_per_piece[2] <= volumes[2], "Volume_Rear")
m.addConstr(A*weight_per_piece[0] + B*weight_per_piece[1] + C*weight_per_piece[2] <= max_loads[0], "Weight_Front")
m.addConstr(A*weight_per_piece[0] + B*weight_per_piece[1] + C*weight_per_piece[2] <= max_loads[1], "Weight_Middle")
m.addConstr(A*weight_per_piece[0] + B*weight_per_piece[1] + C*weight_per_piece[2] <= max_loads[2], "Weight_Rear")
m.addConstr(2000*A + 3000*B + 1500*C >= 0.85 * 2000, "Ratio_Front_Middle")
m.addConstr(3000*B + 1500*C >= 0.85 * 3000, "Ratio_Middle_Rear")
m.addConstr(2000*A + 1500*C >= 0.9 * 2000, "Ratio_Front_Rear")

# Optimize
m.optimize()

# Output results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {v.varName: v.x for v in m.getVars()}}))

