import json
import gurobipy as gp
from gurobipy import GRB

# Coefficients
a = 70
b = 100
purchase_prices = [410, 430, 460, 450]
selling_prices = [425, 440, 465, 455]
max_sales_volumes = [100, 140, 200, 160]
max_storage_capacity = 20

# Create a new model
m = gp.Model()

# Create variables
x_winter = m.addVar(vtype=gp.GRB.INTEGER, name="x_winter", lb=0, ub=None)
x_spring = m.addVar(vtype=gp.GRB.INTEGER, name="x_spring", lb=0, ub=None)
x_summer = m.addVar(vtype=gp.GRB.INTEGER, name="x_summer", lb=0, ub=None)
x_autumn = m.addVar(vtype=gp.GRB.INTEGER, name="x_autumn", lb=0, ub=None)
y = m.addVar(vtype=gp.GRB.CONTINUOUS, name="y", lb=0)

# Add constraints
m.addConstr(x_winter + x_spring + x_summer + x_autumn <= max_storage_capacity, "storage_capacity")
m.addConstr(100 * x_winter >= a * 100 + b * 100 * x_winter, "winter_storage_cost")
m.addConstr(100 * x_spring >= a * 140 + b * 100 * x_spring, "spring_storage_cost")
m.addConstr(100 * x_summer >= a * 200 + b * 100 * x_summer, "summer_storage_cost")
m.addConstr(100 * x_autumn >= a * 160 + b * 100 * x_autumn, "autumn_storage_cost")

# Add objective
m.setObjective(142 * y, GRB.MAXIMIZE)

# Optimize model
m.optimize()

# Print results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {v.varName: v.x for v in m.getVars()}}))

