m.addConstr(sum(raw_material_consumption[i] * x1[i] for i in range(3)) <= raw_material_supply, "c2")

# Objective
m.setObjective(sum(profit_per_unit[i] * x1[i] for i in range(3)), GRB.MAXIMIZE)

# Optimize the model
m.optimize()

# Print the results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {v.varName: v.x for v in m.getVars()}}))

