import json
from gurobipy import *

# Data
availability = {
    "Greenville": 200,
    "Springfield": 150,
    "Riverside": 250,
    "Hilltop": 180
}
demand = {
    "Maplewood": 120,
    "Oakdale": 100,
    "Pineville": 130,
    "Cedarhurst": 90,
    "Brookside": 80
}
distances = {
    "Greenville": {"Maplewood": 10, "Oakdale": 15, "Pineville": 20, "Cedarhurst": 25, "Brookside": 30},
    "Springfield": {"Maplewood": 12, "Oakdale": 8, "Pineville": 18, "Cedarhurst": 22, "Brookside": 28},
    "Riverside": {"Maplewood": 14, "Oakdale": 10, "Pineville": 16, "Cedarhurst": 20, "Brookside": 26},
    "Hilltop": {"Maplewood": 16, "Oakdale": 12, "Pineville": 14, "Cedarhurst": 18, "Brookside": 24}
}

# Model
m = Model("bread_delivery")
x = {b: m.addVar(name=b) for b in availability}
y = {b: m.addVar(name=b) for b in availability}
z = {s: m.addVar(name=s) for s in demand}

# Constraints
for b in availability:
    m.addConstr(sum(x[b] for b in availability) == availability[b], "Supply_" + b)
for s in demand:
    m.addConstr(sum(y[s] for s in demand) == demand[s], "Demand_" + s)
for b in availability:
    for s in demand:
        m.addConstr(x[b] + y[s] >= z[s], "Supply_Demand_" + b + "_" + s)
for b in availability:
    for s in demand:
        m.addConstr(x[b] * distances[b][s] ** 0.5 + y[s] * distances[b][s] ** 0.5 <= z[s], "Distance_" + b + "_" + s)

# Objective
m.setObjective(sum(z[s] for s in demand), "min")

# Optimize
m.optimize()

# Output results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {v.varName: v.x for v in m.getVars()}}))

