risk_costs = {(0, 'U0'): 194.98, (0, 'U1'): 142.38, (0, 'U2'): 54.37, (0, 'U3'): 139.65, (1, 'U0'): 63.28, (1, 'U1'): 186.57, (1, 'U2'): 92.3, (1, 'U3'): 105.4, (2, 'U0'): 67.56, (2, 'U1'): 129.91, (2, 'U2'): 84.63, (2, 'U3'): 151.45}
penalty_costs = {('S0', 'U0'): 85.33, ('S0', 'U1'): 65.23, ('S1', 'U0'): 85.33, ('S1', 'U1'): 65.23}
