        m.addConstr(sum(x[depot][unit] * volume_per_supply[i] for i in range(3)) <= depot_supplies[depot][unit], f"c2_{depot}_{unit}")
        m.addConstr(sum(y[depot][unit] * volume_per_supply[i] for i in range(3)) >= unit_demands[unit][depot], f"c3_{depot}_{unit}")
        m.addConstr(sum(y[depot][unit] * volume_per_supply[i] for i in range(3)) <= depot_supplies[depot][unit], f"c4_{depot}_{unit}")
        m.addConstr(sum(z[depot][unit] * volume_per_supply[i] for i in range(3)) >= unit_demands[unit][depot], f"c5_{depot}_{unit}")
        m.addConstr(sum(z[depot][unit] * volume_per_supply[i] for i in range(3)) <= depot_supplies[depot][unit], f"c6_{depot}_{unit}")

