import json
from gurobipy import *

# Problem data
service_hours_cost = 8.22
audit_cost = 3.22
service_hours_lb = 0
service_hours_ub = 7.94
audit_lb = 0
audit_ub = 18.2
service_hours_points = 8.27
audit_points = 0.96
service_level_target = 31.96
compliance_target = -0.24

# Create a new model
m = Model("service_compliance_optimization")

# Create variables
x = m.addVar(vtype=GRB.INTEGER, name="x", lb=service_hours_lb, ub=service_hours_ub)
y = m.addVar(vtype=GRB.CONTINUOUS, name="y", lb=audit_lb, ub=audit_ub)

# Add objective
m.setObjective(x * service_hours_cost + y * audit_cost, GRB.MINIMIZE)

# Add constraints
m.addConstr(x * service_hours_points + y * audit_points >= service_level_target, "c1")
m.addConstr(x <= service_hours_cost * service_hours_ub, "c2")
m.addConstr(y <= audit_cost * audit_ub, "c3")

# Optimize model
m.optimize()

# Extract results
print(json.dumps({"objective_value": float(m.objVal), "assignment": {v.varName: v.x for v in m.getVars()}}))

